	const lines = src.replace(/\r\n/g, "\n").split("\n");
	let list: "ul" | "ol" | null = null; // 'ul' | 'ol' while one is open
	let para: string[] = [];
	let fence: string[] | null = null; // buffered code-block lines while inside ```

	const closeList = () => {
		if (list) {
