    if let Some(alias) = thinking_alias(&filtered) {
        return Ok(alias.to_owned());
    }
    if THINKING_LEVELS.contains(&collapsed.as_str()) {
        return Ok(collapsed);
    }
    Err(ModelError(format!(
        "{text:?} is not a thinking level. The levels are {}.",
        THINKING_LEVELS.join(", ")
