            .resolve_model(project, requested_model, requested_thinking)
            .await
        {
            Ok(choice) => (
                pin_thinking(&choice.spec(), &self.agent_thinking),
                String::new(),
            ),
            Err(error) => (fallback, format!("About the model: {error}")),
        }
    }

