function fillSelect(select, values, current) {
    const wanted = values.map((v) => v.value).join("\u0000");
    if (select.dataset.filled !== wanted) {
        select.textContent = "";
        for (const v of values) {
            const option = document.createElement("option");
            option.value = v.value;
